#pragma once
// Dependency-free SVG line chart writer (the project uses no plotting scripts:
// all figures for the report are generated by this C++ code).
#include <string>
#include <vector>

namespace arq {

struct ChartPoint {
    double x;
    double y;
    double err = 0.0;  // symmetric error bar (e.g. 95 % CI)
};

struct ChartSeries {
    std::string name;
    std::vector<ChartPoint> points;
    bool dashed = false;
    int color = -1;  // palette index; -1 = use the series position
};

struct LineChart {
    std::string title;
    std::string xLabel;
    std::string yLabel;
    bool logY = false;
    bool yFromZero = true;
    std::vector<ChartSeries> series;

    std::string toSvg(int width = 760, int height = 460) const;
    void save(const std::string& path) const;
};

/// Simple horizontal ASCII bar chart for the terminal.
std::string asciiBars(const std::vector<std::pair<std::string, double>>& rows, const std::string& unit,
                      int width = 40);

}  // namespace arq
